#include SOURCE
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <numeric>
#include <random>
int main(int argc,char**argv){if(argc!=6)return 2;int n=std::atoi(argv[1]),count=std::atoi(argv[2]),shape=std::atoi(argv[3]),reps=std::atoi(argv[4]),seed=std::atoi(argv[5]);RollbackWeightedUnionFind<std::int64_t> uf(n);std::vector<int> ids(n);std::iota(ids.begin(),ids.end(),0);if(shape==2){std::mt19937 rng(seed);std::shuffle(ids.begin(),ids.end(),rng);}for(int first=0;first<n;first+=count){int last=std::min(n,first+count);if(shape==1){for(int j=first+1;j<last;++j)uf.unite(ids[first],ids[j],j-first);}else for(int step=1;step<count;step*=2)for(int i=first;i+step<last;i+=2*step)uf.unite(ids[i],ids[i+step],step);}std::uint64_t sum=0;auto begin=std::clock();for(int r=0;r<reps;++r){auto gs=uf.groups();sum+=gs.size();for(const auto&g:gs){sum+=g.size();for(int x:g)sum+=x;}}auto end=std::clock();std::printf("%.9f %ju\n",double(end-begin)*1000/CLOCKS_PER_SEC,static_cast<std::uintmax_t>(sum));}

