    template <bool CheckConsistency>
#if defined(__GNUC__) || defined(__clang__)
    [[gnu::noinline]]
#endif
    MergeResult unite_wide(int x, int y, const T& w) {
        auto a = root_weight_unchecked(x);
        auto b = root_weight_unchecked(y);
